13	/// Native text drawing hook. The closure receives borrowed UTF-8 and caller-owned pixels.
14	pub type TextDraw<'a>=dyn FnMut(&str,Rect,Theme,u32,u32,FontFamily,FontWeight,&mut[u8],u32,u32,usize)->bool+'a;
15	pub struct WidgetCanvas<'a>{pub rgba:&'a mut[u8],pub capacity:usize,pub stride:usize,pub width:u32,pub height:u32,pub backing_scale:u32,pub ui_scale:f64,pub text_scale_percent:u8,pub theme:Theme,pub increased_contrast:bool,pub tokens:Tokens,draw_text:Option<&'a mut TextDraw<'a>>,icons:IconCache,geometry:Option<GeometryPreflight>}
