18	 pub fn new_scaled(rgba:&'a mut[u8],capacity:usize,width:u32,height:u32,stride:usize,backing_scale:u32,ui_scale:f64,theme:Theme,increased_contrast:bool,draw_text:Option<&'a mut TextDraw<'a>>)->Option<Self>{let row=(width as usize).checked_mul(4)?;let needed=(height as usize).checked_mul(stride)?;if width==0||height==0||width>MAX_CANVAS_AXIS||height>MAX_CANVAS_AXIS||backing_scale==0||backing_scale>3||!ui_scale.is_finite()||!(1.0..=2.0).contains(&ui_scale)||stride<row||capacity<needed||rgba.len()<capacity{return None}Some(Self{rgba,capacity,stride,width,height,backing_scale,ui_scale,text_scale_percent:100,theme,increased_contrast,tokens:theme_tokens(theme,increased_contrast),draw_text,icons:IconCache::default(),geometry:None})}
19	 pub fn set_text_scale(&mut self,scale:u8)->bool{if !(100..=200).contains(&scale)||scale%25!=0{return false}self.text_scale_percent=scale;true}
20	 pub fn paint_text(&mut self,text:&str,bounds:Rect,color:u32,family:FontFamily,weight:FontWeight,font_points:u32)->bool{if text.len()>MAX_TEXT_BYTES{return false}self.text(text,bounds,color,family,weight,font_points)}
21	 pub fn paint_icon(&mut self,icon:IconKind,bounds:Rect,state:ControlState)->bool{self.icon(icon,bounds,state,None)}
22	 pub fn paint_icon_color(&mut self,icon:IconKind,bounds:Rect,color:u32)->bool{self.icon(icon,bounds,ControlState::Rest,Some(color))}
23	 pub fn paint_state_foreground(&self,state:ControlState)->u32{self.state_fg(state)}
24	 pub fn paint_tree_row(&mut self,spec:&WidgetDrawSpec<'_>)->bool{let mut s=*spec;s.kind=WidgetKind::TreeRow;if !preflight(self,&s){return false}draw_tree_row(self,&s)}
25	 pub fn paint_empty_state(&mut self,spec:&WidgetDrawSpec<'_>)->bool{let mut s=*spec;s.kind=WidgetKind::EmptyState;if !preflight(self,&s){return false}draw_empty(self,&s)}
26	 fn valid(&self)->bool{self.width>0&&self.height>0&&self.width<=MAX_CANVAS_AXIS&&self.height<=MAX_CANVAS_AXIS&&self.backing_scale>0&&self.backing_scale<=3&&self.ui_scale.is_finite()&&(1.0..=2.0).contains(&self.ui_scale)&&(100..=200).contains(&self.text_scale_percent)&&self.text_scale_percent%25==0&&self.stride>=self.width as usize*4&&(self.height as usize).checked_mul(self.stride).is_some_and(|n|self.capacity>=n&&self.rgba.len()>=n)}
27	 fn scale(&self)->f64{self.backing_scale as f64*self.ui_scale}
28	 fn pixel_rect(&self,r:Rect)->Option<Rect>{if let Some(g)=&self.geometry{if !g.check(r,self.scale(),true){return None}}scaled_rect(r,self.scale())}
