    16	    pub(super) fn check(&self, local: Rect, scale: f64, active: bool) -> bool {
    17	        let translated = local.x.checked_add(self.x).zip(local.y.checked_add(self.y));
    18	        let valid = translated.is_some_and(|(x, y)| {
    19	            !active || scaled_rect(Rect { x, y, ..local }, scale).is_some()
    20	        });
    21	        if !valid { self.reject(); }
    22	        valid
    23	    }
    24	}
