    26	/// C scaled_rect rules: round each component, then check both scaled endpoints.
    27	/// A valid off-canvas rectangle stays valid; clipping belongs to the raster/callback.
    28	pub(super) fn scaled_rect(r: Rect, scale: f64) -> Option<Rect> {
    29	    if r.width == 0 || r.height == 0 ||
    30	        r.x.checked_add(r.width).is_none() || r.y.checked_add(r.height).is_none() {
    31	        return None;
    32	    }
    33	    let values = [r.x, r.y, r.width, r.height].map(|v| (v as f64 * scale).round());
    34	    if values.iter().any(|v| !v.is_finite() || *v < 0.0 || *v > u32::MAX as f64) ||
    35	        values[2] < 1.0 || values[3] < 1.0 {
    36	        return None;
    37	    }
    38	    let p = Rect { x: values[0] as u32, y: values[1] as u32,
    39	        width: values[2] as u32, height: values[3] as u32 };
    40	    p.x.checked_add(p.width)?;
    41	    p.y.checked_add(p.height)?;
    42	    Some(p)
    43	}
