    45	/// All composite public entries validate before the first pixel or text callback.
    46	/// No fixed margin: the same component dispatch emits that kind's actual geometry.
    47	pub(super) fn preflight(c: &mut WidgetCanvas<'_>, s: &WidgetDrawSpec<'_>) -> bool {
    48	    if !super::valid_spec(c, s) || scaled_rect(s.bounds, c.scale()).is_none() {
    49	        return false;
    50	    }
    51	    let mut local = *s;
    52	    local.bounds.x = 0;
    53	    local.bounds.y = 0;
    54	    c.geometry = Some(GeometryPreflight { x: s.bounds.x, y: s.bounds.y, valid: Cell::new(true) });
    55	    let result = super::paint_component(c, &local);
    56	    let valid = c.geometry.take().is_some_and(|geometry| geometry.valid.get());
    57	    result && valid
    58	}
