    60	pub(super) fn focus_bounds(s: &WidgetDrawSpec<'_>) -> Option<Rect> {
    61	    let mut r = s.bounds;
    62	    if s.kind == WidgetKind::Dropdown && s.expanded { r.height = 30; }
    63	    // C explicitly clamps the left/top of the focus ring to zero.
    64	    let x = r.x.saturating_sub(3);
    65	    let y = r.y.saturating_sub(3);
    66	    let right = r.x.checked_add(r.width)?.checked_add(3)?;
    67	    let bottom = r.y.checked_add(r.height)?.checked_add(3)?;
    68	    Some(Rect { x, y, width: right.checked_sub(x)?, height: bottom.checked_sub(y)? })
    69	}
